        "a + undosh tovush (a doctor, a teacher, a university). an + unli tovush (an engineer, an hour, an old man). I am a/an + kasb.",
      why: "English needs a or an before most singular countable nouns, especially jobs: I am a nurse, not I am nurse.",
      whyUz: "Ingliz tilida ko‘p birlikdagi sanaladigan otlar, ayniqsa kasblar, oldidan a/an kerak: I am a nurse, I am nurse emas.",
      examples: [
        { en: "I am a student. My mother is a cook.", uz: "Men talabaman. Onam oshpaz." },
        { en: "He is an engineer. He works in a factory.", uz: "U muhandis. U zavodda ishlaydi." },
        { en: "She is a doctor in a hospital.", uz: "U kasalxonada shifokor." },
        { en: "Is your father a driver? — No, he’s a pilot.", uz: "Otangiz haydovchimi? — Yo‘q, u uchuvchi." },
      ],
      negative: {
        form: "I am not a/an + job. He isn’t a/an + job.",
        examples: [
          { en: "I’m not a waiter. I’m a cook.", uz: "Men ofitsiant emasman. Men oshpazman." },
          { en: "She isn’t an office worker. She’s a nurse.", uz: "U ofis xodimi emas. U hamshira." },
        ],
      },
      question: {
        form: "Are you a/an + job? Is he/she a/an + job? What do you do?",
        examples: [
          { en: "Are you a teacher? — No, I’m a student.", uz: "Siz o‘qituvchimisiz? — Yo‘q, men talabaman." },
          { en: "What does she do? — She’s a shop assistant.", uz: "U nima ish qiladi? — U sotuvchi." },
        ],
      },
      mistakes: [
        {
          wrong: "I am engineer.",
          right: "I am an engineer.",
          why: "Singular jobs need a or an.",
          whyUz: "Birlikdagi kasblar oldidan a yoki an kerak.",
        },
        {
          wrong: "She is a engineer.",
          right: "She is an engineer.",
          why: "Engineer starts with a vowel sound, so use an.",
          whyUz: "Engineer unli tovush bilan boshlanadi, shuning uchun an.",
        },
      ],
      contrast: {
        vs: "a vs an (sound, not spelling)",
        a: "a university, a European city (consonant /j/ sound)",
        b: "an hour, an honest man (silent h, vowel sound)",
        note: "Listen to the first sound, not the first letter.",
        noteUz: "Birinchi harfga emas, birinchi tovushga quloq tuting.",
      },
