    id: "a1-15",
    day: 15,
    level: "a1",
    topic: "Present Simple he / she / it -s",
    topicUz: "Present Simple: he / she / it -s",
    cefrCanDo: "Can describe another person’s habits with he/she/it + verb-s and use does/doesn’t in questions and negatives.",
    cefrCanDoUz: "Boshqa odamning odatlarini he/she/it + fe’l-s bilan tasvirlay oladi, savol va inkorda does/doesn’t ishlatadi.",
    grammar: {
      title: "Present Simple with he, she, it",
      titleUz: "He, she, it bilan Present Simple",
      meaning:
        "When the subject is he, she or it, add -s (or -es) to the verb in the Present Simple. Questions and negatives use does/doesn’t + base verb.",
      meaningUz:
        "Ega he, she yoki it bo‘lsa, Present Simple da fe’lga -s (yoki -es) qo‘shiladi. Savol va inkorda does/doesn’t + asosiy fe’l ishlatiladi.",
      form: "He/She/It + verb-s: she works, he goes, it starts. -es after o, s, sh, ch, x: goes, watches, finishes. y → ies: studies. have → has. do → does.",
      formUz:
        "He/She/It + fe’l-s: she works, he goes. o, s, sh, ch, x dan keyin -es: goes, watches. y → ies: studies. have → has. do → does.",
      why: "You need this form to talk about family, friends, jobs and daily facts that are not about you.",
      whyUz: "Oila, do‘stlar, kasb va o‘zingiz haqida bo‘lmagan kundalik faktlar uchun shu shakl kerak.",
      examples: [
        { en: "She works in a hospital. He lives in Bukhara.", uz: "U kasalxonada ishlaydi. U Buxoroda yashaydi." },
        { en: "The shop opens at nine. It closes at eight.", uz: "Do‘kon soat to‘qqizda ochiladi. U soat sakkizda yopiladi." },
        { en: "He doesn’t like coffee. She doesn’t go by car.", uz: "U kofeni yoqtirmaydi. U mashinada bormaydi." },
        { en: "Does she teach English? — Yes, she does.", uz: "U ingliz tilidan dars beradimi? — Ha." },
      ],
      negative: {
        form: "He/She/It + doesn’t + base verb. doesn’t = does not. No -s on the main verb.",
        examples: [
          { en: "He doesn’t watch TV in the morning.", uz: "U ertalab televizor ko‘rmaydi." },
          { en: "She doesn’t have a car. She has a bike.", uz: "Uning mashinasi yo‘q. Uning velosipedi bor." },
        ],
      },
      question: {
        form: "Does he/she/it + base verb? Short answers: Yes, she does. / No, it doesn’t.",
        examples: [
          { en: "Does he play the guitar? — No, he doesn’t.", uz: "U gitara chaladimi? — Yo‘q." },
          { en: "Does the class start at nine? — Yes, it does.", uz: "Dars soat to‘qqizda boshlanadimi? — Ha." },
        ],
      },
      mistakes: [
        {
          wrong: "She don’t like tea. He work here.",
          right: "She doesn’t like tea. He works here.",
          why: "He/she/it needs -s in positive sentences and doesn’t (not don’t) in negatives.",
          whyUz: "He/she/it tasdiqda -s, inkorda doesn’t (don’t emas) oladi.",
        },
        {
          wrong: "Does she works here? She doesn’t works here.",
          right: "Does she work here? She doesn’t work here.",
          why: "After does/doesn’t the verb stays in the base form.",
          whyUz: "Does/doesn’t dan keyin fe’l asosiy shaklda qoladi.",
        },
      ],
      contrast: {
        vs: "do vs does",
        a: "I/you/we/they do / don’t + verb",
        b: "he/she/it does / doesn’t + verb",
        note: "Does already has the -s, so the next verb has no -s.",
        noteUz: "Does da allaqachon -s bor, shuning uchun keyingi fe’lda -s yo‘q.",
      },
    },
