      meaning:
        "Some food words are countable (an apple, two eggs). Some are uncountable (bread, rice, water, tea). We do not say two breads in everyday English; we say some bread or a loaf of bread.",
      meaningUz:
        "Ba’zi ovqat so‘zlari sanaladi (an apple, two eggs). Ba’zilari sanalmaydi (bread, rice, water, tea). Kundalik tilda two breads deyilmaydi; some bread yoki a loaf of bread deyiladi.",
      form: "Countable singular: a/an + noun. Countable plural: numbers or some + noun-s. Uncountable: some + noun (no -s, no a/an). I like + food. I don’t like + food.",
      formUz:
        "Sanaladigan birlik: a/an + ot. Ko‘plik: son yoki some + ot-s. Sanalmaydigan: some + ot (-s yo‘q, a/an yo‘q). I like + ovqat.",
      why: "You need this to order food, shop, and talk about meals without sounding unnatural.",
